-- A restrictive policy ANDs active-account checks with the existing shop/role policies.
-- Profile reads intentionally remain available so revoked users can observe logout state.
CREATE POLICY hardening_active_account ON public.products_staff_view AS RESTRICTIVE FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM public.profiles AS caller WHERE caller.id = (SELECT auth.uid()) AND (caller.role = 'owner' OR (caller.role IN ('staff','manager') AND caller.access_enabled IS TRUE AND (caller.access_mode = 'no_restriction' OR caller.access_expires_at > now()))))) WITH CHECK (EXISTS (SELECT 1 FROM public.profiles AS caller WHERE caller.id = (SELECT auth.uid()) AND (caller.role = 'owner' OR (caller.role IN ('staff','manager') AND caller.access_enabled IS TRUE AND (caller.access_mode = 'no_restriction' OR caller.access_expires_at > now())))));
